// Deterministic seed shuffle for 4 options to avoid obvious answer patterns
const answerPositions = Array.from({length: rawQuestions.length}, (_, i) => i % 4);
let questionSeed = 260710;
for (let i = answerPositions.length - 1; i > 0; i--) {
    questionSeed = (Math.imul(questionSeed, 1664525) + 1013904223) >>> 0;
    const j = questionSeed % (i + 1);
    [answerPositions[i], answerPositions[j]] = [answerPositions[j], answerPositions[i]];
}

rawQuestions.forEach((q, idx) => {
    const target = answerPositions[idx];
    const order = [1, 2, 3];
    order.splice(target, 0, 0);
    window.QUESTIONS.push({
        id: idx + 1,
        chapter: q.chapter,
        question: q.question,
        options: order.map(i => q.options[i]),
        feedback: order.map(i => q.feedback[i]),
        answer: target,
        hint: q.hint
    });
});

